/* Returns half the signed 12-bit wrapped angle difference (target - current), rounded away from zero and clamped to +/-maxStep. */ f32 getClampedAngleStep12(f32 current, f32 target, f32 maxStep) {
    f32 negMax;
    f32 step;
    s32 delta;
    s32 biased;

    delta = (s32) (((s32) target - (s32) current) << 0x14) >> 0x14;
    step = 0.0f;
    if (delta != 0) {
        if (delta >= 0) {
            biased = delta + 1;
        } else {
            biased = delta - 1;
        }
        do {
            step = (f32) (biased >> 1);
        } while (0);
        negMax = -maxStep;
        if (step < negMax) {
            step = negMax;
        } else if (maxStep < step) {
            step = maxStep;
        }
    }
    return step;
}
